CREATE DATABASE IF NOT EXISTS ecommerce_customer_analysis;
USE ecommerce_customer_analysis;
DROP TABLE IF EXISTS ecommerce_orders;
CREATE TABLE ecommerce_orders (
    order_id INT NOT NULL PRIMARY KEY,
    order_date DATETIME NOT NULL,
    customer_id INT NOT NULL,
    gender VARCHAR(10) NOT NULL,
    age TINYINT UNSIGNED NOT NULL,
    city VARCHAR(40) NOT NULL,
    product_category VARCHAR(30) NOT NULL,
    product_name VARCHAR(60) NOT NULL,
    quantity TINYINT UNSIGNED NOT NULL,
    unit_price DECIMAL(10,2) NOT NULL,
    discount_pct TINYINT UNSIGNED NOT NULL,
    payment_method VARCHAR(30) NOT NULL,
    device_type VARCHAR(15) NOT NULL,
    order_status VARCHAR(15) NOT NULL
);

-- Insert in batches of 100 rows. No Import Wizard / CSV column mapping needed.

SELECT COUNT(*) AS total_rows FROM ecommerce_orders;
SELECT * FROM ecommerce_orders LIMIT 10;